/**
 * @summary Verify a vote receipt (public, no auth required)
 */
export const getVerifyVoteReceiptUrl = (params: VerifyVoteReceiptParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/votes/verify?${stringifiedParams}`
    : `/api/votes/verify`;
};

export const verifyVoteReceipt = async (
  params: VerifyVoteReceiptParams,
  options?: RequestInit,
): Promise<ReceiptVerification> => {
  return customFetch<ReceiptVerification>(getVerifyVoteReceiptUrl(params), {
    ...options,
    method: "GET",
  });
};

